/* @autogenerated */
import { Observable } from 'rxjs';

/** Las tres versiones de una entidad tras un 412 por bloqueo optimista. */
export interface EditConflict<T> {
  /** Valor cargado en el formulario al abrir la edición. */
  original: T;
  /** Valor que el usuario intentó guardar. */
  sent: T;
  /** Valor vigente en el servidor. */
  current: T;
}

/**
 * Estado de un campo en la fusión:
 * - `unchanged`: nadie lo ha cambiado.
 * - `mine`: solo lo ha cambiado el usuario.
 * - `theirs`: solo ha cambiado en el servidor.
 * - `same`: ambos lo han cambiado al mismo valor.
 * - `conflict`: ambos lo han cambiado con valores distintos.
 */
export type FieldMergeState = 'unchanged' | 'mine' | 'theirs' | 'same' | 'conflict';

/** Versión de la que se toma el valor de un campo. */
export type FieldMergeChoice = 'sent' | 'current';

export interface FieldMerge {
  field: string;
  original: unknown;
  sent: unknown;
  current: unknown;
  state: FieldMergeState;
  /** Versión elegida; `null` en un `conflict` todavía sin resolver. */
  choice: FieldMergeChoice | null;
  /** Valor elegido: `sent` en `mine`, `current` en `theirs`/`same`/`unchanged`, sin valor en `conflict`. */
  resolved?: unknown;
}

export interface ThreeWayMergeOptions {
  /** Campos que no se comparan: se toman siempre de `current`. Por defecto `version` y `uid`. */
  ignore?: string[];
}

/** Campo que se muestra al resolver un conflicto. */
export interface ConflictField {
  name: string;
  /** Clave de traducción del campo (la de `form-group.*`): se traduce `<label>.label`, igual que en los editables. */
  label: string;
  /** Texto legible del valor (referencias `$ref`, enums, fechas…); por defecto se formatea el valor tal cual. */
  display?: (value: any) => string | Observable<string>;
}

/** Error que emite `RepositoryService.update` cuando el servidor rechaza el guardado con 412. */
export class EditConflictError<T> extends Error {
  override readonly name = 'EditConflictError';

  /** `cause` es la respuesta HTTP original (412). */
  constructor(
    readonly conflict: EditConflict<T>,
    cause: unknown,
  ) {
    super('Edit conflict: the item has been modified by someone else', { cause });
  }
}

export function isEditConflict<T = any>(err: unknown): err is EditConflictError<T> {
  return err instanceof EditConflictError;
}
